/* @autogenerated */
package net.civeira.phylax.features.oauth.maintenance;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.sql.Timestamp;

import javax.sql.DataSource;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

/**
 * Application service that deletes expired OAuth records from the database.
 *
 * <p>
 * Targets {@code _oauth_temporal_codes} and {@code _oauth_sessions}. Each method runs in its own
 * transaction and returns the number of deleted rows.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class OAuthCleanupService {

  private final DataSource source;

  /**
   * Deletes all rows from {@code _oauth_temporal_codes} whose {@code expiration} is in the past.
   *
   * @return number of deleted rows
   */
  @Transactional
  public int deleteExpiredTemporalCodes() {
    try (Connection conn = source.getConnection();
        PreparedStatement ps =
            conn.prepareStatement("DELETE FROM _oauth_temporal_codes WHERE expiration < ?")) {
      ps.setTimestamp(1, new Timestamp(System.currentTimeMillis()));
      int deleted = ps.executeUpdate();
      log.info("Cleaned {} expired temporal codes", deleted);
      return deleted;
    } catch (SQLException ex) {
      throw new IllegalStateException("Failed to clean expired temporal codes", ex);
    }
  }

  /**
   * Deletes all rows from {@code _oauth_sessions} whose {@code expiration} is in the past.
   *
   * @return number of deleted rows
   */
  @Transactional
  public int deleteExpiredSessions() {
    try (Connection conn = source.getConnection();
        PreparedStatement ps =
            conn.prepareStatement("DELETE FROM _oauth_sessions WHERE expiration < ?")) {
      ps.setTimestamp(1, new Timestamp(System.currentTimeMillis()));
      int deleted = ps.executeUpdate();
      log.info("Cleaned {} expired sessions", deleted);
      return deleted;
    } catch (SQLException ex) {
      throw new IllegalStateException("Failed to clean expired sessions", ex);
    }
  }
}
